import pandas as pd, numpy as np
from math import radians, sin, cos, asin, sqrt
from scipy.stats import pearsonr, spearmanr
r=pd.read_csv('/app/dataset/readings.csv', parse_dates=['timestamp'])
s=pd.read_csv('/app/dataset/stations.csv')
wr=pd.read_csv('/app/dataset/weather_readings.csv', parse_dates=['timestamp'])
ws=pd.read_csv('/app/dataset/weather_stations.csv')
r=r.merge(s,on='station_id')
ts=sorted(r.timestamp.unique())
Y=r.pivot(index='timestamp', columns='station_id', values='current_reading').reindex(ts)
meta=s.set_index('station_id')
pol=r.groupby('station_id').pollutant.first()
ids=list(meta.index)
wmeta=ws.set_index('weather_station_id')
W={}
for var in ['temperature_c','humidity_pct','wind_speed_m_s','rain_accumulation_mm']:
    W[var]=wr.pivot(index='timestamp', columns='weather_station_id', values=var).reindex(ts)

def hav(lat1,lon1,lat2,lon2):
    R=6371.0
    lat1,lon1,lat2,lon2=map(radians,[lat1,lon1,lat2,lon2])
    dlat=lat2-lat1; dlon=lon2-lon1
    a=sin(dlat/2)**2+cos(lat1)*cos(lat2)*sin(dlon/2)**2
    return 2*R*asin(sqrt(a))
# distances
dist_air=pd.DataFrame(index=ids,columns=ids,dtype=float)
for i in ids:
 for j in ids:
  dist_air.loc[i,j]=hav(meta.loc[i,'latitude'],meta.loc[i,'longitude'],meta.loc[j,'latitude'],meta.loc[j,'longitude'])
# weather nearest
nearest_ws={}
for sid in ids:
 dists={wid:hav(meta.loc[sid,'latitude'],meta.loc[sid,'longitude'],wmeta.loc[wid,'latitude'],wmeta.loc[wid,'longitude']) for wid in wmeta.index}
 nearest_ws[sid]=min(dists, key=dists.get)

def corr(a,b):
    a=np.asarray(a,float); b=np.asarray(b,float)
    m=np.isfinite(a)&np.isfinite(b)
    if m.sum()<6: return np.nan, m.sum()
    if np.nanstd(a[m])==0 or np.nanstd(b[m])==0: return np.nan, m.sum()
    return np.corrcoef(a[m],b[m])[0,1], m.sum()

def residual(y,b):
    a=np.asarray(y,float); bb=np.asarray(b,float)
    m=np.isfinite(a)&np.isfinite(bb)
    if m.sum()<6: return np.full_like(a,np.nan), (np.nan,np.nan,np.nan)
    X=np.vstack([np.ones(m.sum()),bb[m]]).T
    coef=np.linalg.lstsq(X,a[m],rcond=None)[0]
    res=np.full_like(a,np.nan)
    res[m]=a[m] - X@coef
    ss=np.sum((a[m]-a[m].mean())**2); r2=1-np.sum(res[m]**2)/ss if ss>0 else np.nan
    return res,(coef[0],coef[1],r2)

def peer_ids(sid, mtype):
    candidates=[x for x in ids if x!=sid and pol[x]==pol[sid]]
    d=meta.loc[sid,'district']
    if mtype=='district':
        ds=[x for x in candidates if meta.loc[x,'district']==d]
        if len(ds)>=2: return ds
    if mtype.startswith('nearest'):
        k=int(mtype.replace('nearest',''))
        return list(dist_air.loc[sid,candidates].sort_values().head(k).index)
    return candidates

def weather_series(sid, source, var):
    if source=='nearest':
        return W[var][nearest_ws[sid]].values.astype(float)
    if source=='district_mean':
        d=meta.loc[sid,'district']
        wids=list(wmeta[wmeta.district==d].index)
        return W[var][wids].mean(axis=1).values.astype(float)
    if source=='nearest_district':
        d=meta.loc[sid,'district']
        wids=list(wmeta[wmeta.district==d].index)
        # nearest among district only
        wid=min(wids, key=lambda wid:hav(meta.loc[sid,'latitude'],meta.loc[sid,'longitude'],wmeta.loc[wid,'latitude'],wmeta.loc[wid,'longitude']))
        return W[var][wid].values.astype(float)
rows=[]
for sid in ids:
 y=Y[sid].values.astype(float)
 for mtype in ['district','nearest5','nearest8','all']:
  peers=peer_ids(sid,mtype)
  b=Y[peers].mean(axis=1, skipna=True).values.astype(float)
  res,(alpha,beta,r2)=residual(y,b)
  # also raw y weather correlation and baseline/weather maybe useful
  for source in ['nearest','nearest_district','district_mean']:
   for var in ['temperature_c','humidity_pct','wind_speed_m_s','rain_accumulation_mm']:
    wx=weather_series(sid, source, var)
    c,n=corr(res,wx)
    cy,_=corr(y,wx)
    cb,_=corr(b,wx)
    rows.append(dict(sid=sid, pol=pol[sid], district=meta.loc[sid,'district'], mtype=mtype, source=source, var=var, count=np.isfinite(y).sum(), corr_res=c, abs_corr=abs(c) if np.isfinite(c) else np.nan, corr_y=cy, corr_b=cb, beta=beta, r2=r2, res_std=np.nanstd(res,ddof=1), mean=np.nanmean(y), std=np.nanstd(y,ddof=1)))
R=pd.DataFrame(rows)
for mtype in ['district','nearest5','nearest8','all']:
 for source in ['nearest','nearest_district','district_mean']:
  print('\n---',mtype,source,'top abs residual weather corr---')
  top=R[(R.mtype==mtype)&(R.source==source)].sort_values('abs_corr',ascending=False).head(20)
  print(top[['sid','pol','district','var','corr_res','corr_y','corr_b','count','mean','std','beta','r2','res_std']].to_string(index=False))
